import org.apache.commons.cli.CommandLine;
import org.apache.commons.cli.Option;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.function.Supplier;

import static org.junit.jupiter.api.Assertions.*;

public class CommandLineGetParsedOptionValuesTest {

    private CommandLine newCommandLine(List<Option> options) throws Exception {
        Constructor<CommandLine> ctor = CommandLine.class.getDeclaredConstructor(List.class, List.class, java.util.function.Consumer.class);
        ctor.setAccessible(true);
        return ctor.newInstance(new ArrayList<String>(), options, null);
    }

    private Option callResolveOption(CommandLine cl, String name) throws Exception {
        Method m = CommandLine.class.getDeclaredMethod("resolveOption", String.class);
        m.setAccessible(true);
        return (Option) m.invoke(cl, name);
    }

    @Test
    public void returnsValuesForShortOption() throws Exception {
        Option opt = new Option("o", "opt", true, "description");
        opt.addValueForProcessing("v1");
        opt.addValueForProcessing("v2");

        CommandLine cl = newCommandLine(Arrays.asList(opt));

        Supplier<String[]> defaultSup = () -> new String[]{"def"};
        String[] values = cl.getParsedOptionValues("o", defaultSup);

        assertArrayEquals(new String[]{"v1", "v2"}, values);
    }

    @Test
    public void returnsValuesForLongOptionAndWithHyphens() throws Exception {
        Option opt = new Option("o", "opt", true, "description");
        opt.addValueForProcessing("long1");

        CommandLine cl = newCommandLine(Arrays.asList(opt));

        Supplier<String[]> defaultSup = () -> new String[]{"def"};

        // long name without hyphens
        String[] valuesLong = cl.getParsedOptionValues("opt", defaultSup);
        assertArrayEquals(new String[]{"long1"}, valuesLong);

        // long name with double hyphen
        String[] valuesHyphen = cl.getParsedOptionValues("--opt", defaultSup);
        assertArrayEquals(new String[]{"long1"}, valuesHyphen);

        // short with single hyphen
        String[] valuesShortHyphen = cl.getParsedOptionValues("-o", defaultSup);
        assertArrayEquals(new String[]{"long1"}, valuesShortHyphen);
    }

    @Test
    public void returnsDefaultWhenOptionMissingOrNullName() throws Exception {
        CommandLine cl = newCommandLine(new ArrayList<>());

        Supplier<String[]> defaultSup = () -> new String[]{"d1", "d2"};

        // missing option name
        String[] missing = cl.getParsedOptionValues("missing", defaultSup);
        assertArrayEquals(new String[]{"d1", "d2"}, missing);

        // null option name should resolve to null and return default
        String[] nullName = cl.getParsedOptionValues(null, defaultSup);
        assertArrayEquals(new String[]{"d1", "d2"}, nullName);
    }

    @Test
    public void resolveOptionPrivateBehavior() throws Exception {
        Option opt = new Option("s", "some", true, "desc");
        CommandLine cl = newCommandLine(Arrays.asList(opt));

        // exact short
        assertNotNull(callResolveOption(cl, "s"));
        // short with hyphen
        assertNotNull(callResolveOption(cl, "-s"));
        // long without hyphens
        assertNotNull(callResolveOption(cl, "some"));
        // long with hyphens
        assertNotNull(callResolveOption(cl, "--some"));

        // missing option
        assertNull(callResolveOption(cl, "nope"));

        // null argument
        assertNull(callResolveOption(cl, null));
    }
}

